CREATE TEMPORARY VIEW raw_${grass_region_without_quote} AS
    select                                                                                             
        t.regional_date
        ,t.regional_hour
        ,t.country
        ,case
            when t.biz_info.rcmd_info.bundle = 'daily_discover_main' then 'dd' 
            else 'cart' 
        end as bundle
        ,case 
            when t.country = 'ID' then filter(t.ab_sign, x -> x IN (668666, 668667))
            when t.country = 'BR' then filter(t.ab_sign, x -> x IN (668668, 668669))
            when t.country = 'PH' then filter(t.ab_sign, x -> x IN (668670, 668671))
            when t.country = 'TH' then filter(t.ab_sign, x -> x IN (668672, 668673))
            when t.country = 'VN' then filter(t.ab_sign, x -> x IN (668674, 668675))
            when t.country = 'MY' then filter(t.ab_sign, x -> x IN (668676, 668677))
            when t.country = 'TW' then filter(t.ab_sign, x -> x IN (668678, 668679))
            when t.country = 'SG' then filter(t.ab_sign, x -> x IN (668680, 668681))
        end as ab_signs
        ,t.request_id
        ,cardinality(t.data) as item_cnt_per_request
        ,t.data
    from srdi_rt.ods_fll_rcmd t
    where 1=1
    and t.regional_date = ${regional_date}
    and t.regional_hour= ${regional_hour}
    and t.country IN (${grass_region})
    and t.sample_info.full_link_all = true
    and t.biz_info.rcmd_info.bundle IN ('daily_discover_main','shoppingcart','orderpaid_discover','my_purchases_page_ymal','order_detail_page_ymal')
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW exploded_${grass_region_without_quote} AS
    select 
        regional_date
        ,regional_hour
        ,country
        ,bundle
        ,cast(abt as string) as abt
        ,case 
            when d.item_type IN ('ROI1','TARGET_ROI2','SIMPLE_ROI2') THEN 'true'
            else 'false'
        end as is_ads
        ,cast(recall_queue_id as string) as recall_queue_id
        ,case
            when d.card_type = 'ITEM' then 'ITEM'
            when d.card_type = 'VIDEO' then 'VIDEO'
            when d.card_type = 'STREAM' then 'STREAM'
            else 'OTHER'
        end as card_type
        ,stage
        ,request_id
        ,item_cnt_per_request
        ,d.rcmd_unit_info.llm_cluster_v2
    from raw_${grass_region_without_quote} 
    lateral view outer explode (ab_signs) as abt
    lateral view explode (data) as d
    lateral view explode (array_remove(
        array(
            if(d.recall_info IS NOT NULL,'RECALL', ''),
            if(d.prerank_info IS NOT NULL, 'PRERANK', ''),
            if(d.rank_info IS NOT NULL, 'RANK', ''),
            if(d.mixrank_info IS NOT NULL or d.filtered_reason='MIXRANK_TRUNCATED', 'MIXRANK', ''),
            if(d.final_stage = 'DISPATCH', 'DISPATCH', '')
        ),'')
    ) AS stage
    lateral view outer explode (transform(d.recall_info.strategies, x -> x.queue_id)) as recall_queue_id
;

--sql_divide_splitter--
CREATE TEMPORARY VIEW uniq_req_pre_${grass_region_without_quote} AS
    select 
        regional_date
        ,regional_hour
        ,country
        ,bundle
        ,if(grouping(abt)=1,'__ALL__',abt) as abt
        ,if(grouping(is_ads)=1,'__ALL__',is_ads) as is_ads
        ,if(grouping(recall_queue_id)=1,'__ALL__',recall_queue_id) as recall_queue_id
        ,card_type
        ,stage
        ,item_cnt_per_request
        ,request_id
    from exploded_${grass_region_without_quote}
    group by 
        regional_date,regional_hour,country,bundle,CUBE(abt, is_ads, recall_queue_id),card_type,stage,item_cnt_per_request,request_id
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW uniq_req_${grass_region_without_quote} AS
    select
        regional_date
        ,regional_hour
        ,country
        ,bundle
        ,abt
        ,is_ads
        ,recall_queue_id
        ,card_type
        ,stage
        ,sum(item_cnt_per_request) as item_cnt
        ,count(1) as unique_request_cnt
    from uniq_req_pre_${grass_region_without_quote}
    group by 
        regional_date,regional_hour,country,bundle,abt,is_ads,recall_queue_id,card_type,stage
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW uniq_llm_pre_${grass_region_without_quote} AS
    select 
        regional_date
        ,regional_hour
        ,country
        ,bundle
        ,if(grouping(abt)=1,'__ALL__',abt) as abt
        ,if(grouping(is_ads)=1,'__ALL__',is_ads) as is_ads
        ,if(grouping(recall_queue_id)=1,'__ALL__',recall_queue_id) as recall_queue_id
        ,card_type
        ,stage
        ,request_id
        ,llm_cluster_v2
    from exploded_${grass_region_without_quote}
    group by 
        regional_date,regional_hour,country,bundle,CUBE(abt, is_ads, recall_queue_id),card_type,stage,request_id,llm_cluster_v2
