--sql_divide_splitter--
CREATE TEMPORARY VIEW uniq_llm_${grass_region_without_quote} AS
    select
        regional_date
        ,regional_hour
        ,country
        ,bundle
        ,abt
        ,is_ads
        ,recall_queue_id
        ,card_type
        ,stage
        ,count(1) as unique_llm_cluster_count
    from uniq_llm_pre_${grass_region_without_quote}
    group by 
        regional_date,regional_hour,country,bundle,abt,is_ads,recall_queue_id,card_type,stage
;

