INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_fll_diversity_funnel_1h
partition(regional_date=${regional_date}, regional_hour=${regional_hour}, country = ${grass_region})
select
    a.bundle
    ,a.abt
    ,a.is_ads
    ,a.recall_queue_id
    ,a.card_type
    ,a.stage
    ,unique_llm_cluster_count
    ,unique_llm_cluster_count / cast(unique_request_cnt as double) as unique_llm_cluster_per_req
    ,unique_llm_cluster_count / cast(item_cnt as double) as llm_cluster_density
from uniq_llm_${grass_region_without_quote} a
left join uniq_req_${grass_region_without_quote} b 
    on a.country = b.country
    and a.bundle = b.bundle
    and a.abt = b.abt
    and a.is_ads = b.is_ads
    and a.recall_queue_id = b.recall_queue_id
    and a.card_type = b.card_type
    and a.stage = b.stage
